```ts
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { interpolateArcRotateCamera } from "@babylonjs/lite";

export function spinAround(camera: ArcRotateCamera, scene: SceneContext, turns: number): Promise<void> {
  const startAlpha = camera.alpha;
  const targetAlpha = startAlpha + Math.PI * 2 * turns;

  return interpolateArcRotateCamera(camera, scene, { alpha: targetAlpha });
}
```

I wrote `src/turntable.ts` to use the library’s `interpolateArcRotateCamera` with only an alpha goal, so distance, beta, and target are left untouched. I’m not sure whether that API normalizes/wraps alpha or respects existing alpha limits; if it does, a full-turn spin may need chunking or temporary limit changes.
